/**
 * Stem Studio effect modules, stem-type chains and presets.
 *
 * Three preset families:
 *   desktop  the Liminal desktop app's own presets and per-stem module chains, extracted verbatim
 *            (desktop-data.js, generated by scripts/extract-desktop-presets.mjs)
 *   classic  the 23 presets of the earlier "DeepSplit" engine (fx_engine.py), expressed in Studio
 *            primitives (peq / gate / compressor / limiter / drive / bitcrush / reverb / chorus / gain)
 *   studio   new presets for the drum sub-stems and 808 that the desktop app does not have
 *
 * The desktop's effect *engine* is Spotify's pedalboard (GPL-3.0). Studio re-implements every module
 * from its published parameters in public/stem-studio/dsp/ (no code copied). See docs/stem-studio-presets.md
 * for the per-module fidelity table.
 */
import { DESKTOP } from './desktop-data.js';

export const DESKTOP_MODULES = DESKTOP.ALL_FX_MODULES;
export const DESKTOP_CHAINS = DESKTOP.STEM_FX_CHAINS;

/* ---------- module specs (what the UI renders) ---------- */
const clone = (o) => JSON.parse(JSON.stringify(o));
const P = (id, label, value, min, max, step, unit = '', extra = {}) => ({ id, label, value, min, max, step, unit, ...extra });

/** Fidelity of each module vs. the desktop engine: exact | approx | fixed (intent honoured where desktop drops a key) | studio (new) */
const FIDELITY = {
  gate: ['exact', 'JUCE-style expander, stereo-linked (pedalboard detects per channel).'],
  dereverb: ['exact', 'Same as desktop: a gate with ratio 1 + amount/10, attack 10 ms. It is an expander, not a spectral de-reverb; use Artifact Cleanup > De-reverb tails for a spectral one.'],
  deesser: ['approx', 'Default mode is a split-band de-esser (only the sibilant band is reduced). "Desktop" mode reproduces the desktop hybrid (-3 dB cut at the frequency + 5:1 compressor on the whole signal).'],
  compressor: ['fixed', 'JUCE compressor law, hard knee, linked. Auto makeup (70 % of static reduction when makeup = 0) + -0.5 dB limiter as on desktop. The desktop ignores the Mix knob; Studio honours it (parallel compression).'],
  eq: ['exact', 'Low shelf 200 Hz, peak (Q 1) at Mid Freq, high shelf 5 kHz, with the desktop "smart curves" (30 Hz HPF when Low > 3 dB, +25 % air shelf at 12 kHz when High > 2 dB). RBJ biquads like JUCE.'],
  saturation: ['fixed', '60 Hz head bump -> tanh drive (drive x 0.35 dB) -> -0.3 dB clip -> 14 kHz low-pass. The desktop ignores the Mix knob; Studio honours it.'],
  reverb: ['approx', 'Freeverb/JUCE topology and constants, desktop mapping (dry = 1 - wet/2, damping floor 60 % above 60 % room, 300 Hz mud cut when wet > 30 %). Desktop sends the dry gain through JUCE x2 scaling (louder); Studio keeps unity dry. Width above 100 % is clamped (as JUCE).'],
  delay: ['fixed', 'Same delay/feedback/mix. Desktop puts a 4 kHz low-pass before the delay (dulling the dry signal) when feedback > 40 %; Studio puts it in the feedback loop only (the evident intent).'],
  chorus: ['approx', 'Modulated stereo delay (quadrature LFOs). JUCE chorus internals are not published, so depth scaling is matched by ear.'],
  loudness: ['exact', 'Same flow as desktop: input gain -> 20:1 compressor at the ceiling (1 ms / 100 ms) -> hard clip at the ceiling. Not a true-peak limiter: Export applies a true-peak safe stage.'],
  'stereo-width': ['fixed', 'Mid/side with the side high-passed at 120 Hz (bass stays mono), side x width, 15 % 10 ms Haas copy above 120 %. Runs in chain position (desktop applies it after the whole chain). The Haas copy uses a true delay line (desktop wraps with np.roll).'],
  filter: ['exact', 'First-order (6 dB/oct) HP when > 20 Hz and LP when < 19 kHz, like pedalboard.'],
  phaser: ['fixed', '6-stage all-pass phaser around 1.3 kHz. The desktop passes preset mix values such as 40 straight to a 0-1 parameter, which makes pedalboard throw and silently drop the phaser; Studio treats values > 1 as percent.'],
  pitch: ['approx', 'Phase-vocoder pitch shift (fft 2048, 8x overlap, ~37 ms latency, compensated). pedalboard uses Rubber Band (GPL); expect more phasiness on vocals at +-12.'],
  peq: ['studio', 'Parametric band: peak / low shelf / high shelf / first-order or 12 dB/oct HP/LP / notch.'],
  gain: ['studio', 'Plain gain.'], limiter: ['studio', 'Look-ahead brick-wall limiter (1.5 ms).'],
  drive: ['studio', 'tanh drive (Classic presets).'], bitcrush: ['studio', 'Bit-depth reduction (Classic presets).'],
};

const specs = clone(DESKTOP_MODULES);
// extras that let the Studio honour desktop preset keys the desktop engine accepts but its UI never exposed
specs.compressor.params.push(P('attack', 'Attack', 10, 0.1, 100, 0.1, 'ms', { extra: true }), P('release', 'Release', 100, 10, 1000, 10, 'ms', { extra: true }), P('autoMakeup', 'Auto makeup', 1, 0, 1, 1, '', { extra: true, kind: 'toggle' }));
specs.deesser.params.push(P('mode', 'Mode', 'split', 0, 0, 0, '', { extra: true, kind: 'select', options: [['split', 'Split-band'], ['desktop', 'Desktop hybrid']] }), P('ratio', 'Ratio', 5, 1, 20, 0.5, ':1', { extra: true }));
specs.phaser.params.find((p) => p.id === 'mix').unit = '';
specs.peq = { id: 'peq', name: 'Parametric Band', description: 'Single EQ band', category: 'eq', enabled: false, params: [
  P('type', 'Type', 'peak', 0, 0, 0, '', { kind: 'select', options: [['peak', 'Peak'], ['lowshelf', 'Low shelf'], ['highshelf', 'High shelf'], ['hp', 'High-pass 6 dB'], ['lp', 'Low-pass 6 dB'], ['hp2', 'High-pass 12 dB'], ['lp2', 'Low-pass 12 dB'], ['notch', 'Notch']] }),
  P('freq', 'Freq', 1000, 20, 20000, 1, 'Hz', { log: true }), P('gain', 'Gain', 0, -18, 18, 0.5, 'dB'), P('q', 'Q', 1, 0.1, 10, 0.05, '')] };
specs.gain = { id: 'gain', name: 'Gain', description: 'Level', category: 'dynamics', enabled: false, params: [P('gain', 'Gain', 0, -24, 24, 0.5, 'dB')] };
specs.limiter = { id: 'limiter', name: 'Limiter', description: 'Look-ahead brick-wall', category: 'dynamics', enabled: false, params: [P('threshold', 'Ceiling', -1, -12, 0, 0.1, 'dB'), P('release', 'Release', 100, 10, 1000, 10, 'ms')] };
specs.drive = { id: 'drive', name: 'Drive', description: 'tanh saturation', category: 'creative', enabled: false, params: [P('drive', 'Drive', 10, 0, 40, 0.5, 'dB')] };
specs.bitcrush = { id: 'bitcrush', name: 'Bitcrush', description: 'Bit-depth reduction', category: 'creative', enabled: false, params: [P('bits', 'Bits', 8, 2, 24, 1, 'bit')] };
for (const [id, [fid, note]] of Object.entries(FIDELITY)) { specs[id].fidelity = fid; specs[id].fidelityNote = note; }
export const MODULES = specs;
export const MODULE_IDS = Object.keys(MODULES);

export const defaultParams = (type) => Object.fromEntries(MODULES[type].params.map((p) => [p.id, p.value]));

/* ---------- stems ---------- */
export const STEM_KINDS = {
  vocals: { label: 'Vocals', chain: 'vocals' }, drums: { label: 'Drums', chain: 'drums' }, bass: { label: 'Bass', chain: 'bass' },
  other: { label: 'Other', chain: 'other' }, instrumental: { label: 'Instrumental', chain: 'other' }, guitar: { label: 'Guitar', chain: 'guitar' }, piano: { label: 'Piano', chain: 'piano' },
  kick: { label: 'Kick', chain: 'kick' }, snare: { label: 'Snare / clap', chain: 'snare' }, hats: { label: 'Hi-hats', chain: 'hh' }, toms: { label: 'Toms', chain: 'toms' },
  cymbals: { label: 'Cymbals', chain: 'cymbals' }, ride: { label: 'Ride', chain: 'ride' }, crash: { label: 'Crash', chain: 'crash' }, 'sub808': { label: '808 / sub', chain: 'bass' },
};
export const DRUM_KINDS = ['kick', 'snare', 'hats', 'toms', 'cymbals', 'ride', 'crash', 'sub808'];

/** Map any stem name ("Vocals", "hi-hat", "808", "lead vocal") to a STEM_KINDS id. */
export function stemKind(name) {
  const n = String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (STEM_KINDS[n]) return n;
  if (/808|sub/.test(n)) return 'sub808';
  if (/hi ?hat|^hh$|hats?/.test(n)) return 'hats';
  if (/snare|clap/.test(n)) return 'snare';
  if (/kick|bd/.test(n)) return 'kick';
  if (/tom/.test(n)) return 'toms';
  if (/ride/.test(n)) return 'ride';
  if (/crash/.test(n)) return 'crash';
  if (/cymbal|overhead/.test(n)) return 'cymbals';
  if (/vocal|voice|lead|back|vox/.test(n)) return 'vocals';
  if (/drum|perc/.test(n)) return 'drums';
  if (/bass/.test(n)) return 'bass';
  if (/guitar/.test(n)) return 'guitar';
  if (/piano|keys/.test(n)) return 'piano';
  if (/instrumental|no vocal/.test(n)) return 'instrumental';
  return 'other';
}

/** Module ids (in chain order) the desktop offers for a stem kind. */
export function chainModules(kind) {
  const key = (STEM_KINDS[kind] || STEM_KINDS.other).chain;
  return DESKTOP_CHAINS[key] || DESKTOP_CHAINS.other;
}

/* ---------- desktop presets ---------- */
/** desktop preset key -> module param (the desktop engine reads some keys the UI schema does not declare) */
function normaliseDesktopParams(type, raw) {
  const o = { ...raw }; delete o.enabled;
  if (type === 'eq') { if ('freq' in o) { o.freq_mid = o.freq; delete o.freq; } delete o.width; }
  if (type === 'reverb' && 'mix' in o) { o.wet = o.mix; delete o.mix; }
  if (type === 'phaser' && typeof o.mix === 'number' && o.mix > 1) o.mix /= 100;
  return o;
}
function desktopPresetsFor(kind) {
  const key = (STEM_KINDS[kind] || STEM_KINDS.other).chain;
  const list = DESKTOP.STEM_PRESETS[key] || DESKTOP.STEM_PRESETS[kind] || [];
  const order = chainModules(kind);
  return list.map((pr) => ({
    id: `desktop:${pr.id}`, family: 'desktop', name: pr.label, description: pr.description || '',
    chain: order.filter((t) => pr.fx[t] && pr.fx[t].enabled !== false).map((t) => ({ type: t, enabled: true, params: { ...defaultParams(t), ...normaliseDesktopParams(t, pr.fx[t]) } })),
  }));
}

/* ---------- classic (DeepSplit) presets, in Studio primitives ---------- */
const hp = (freq) => ({ type: 'peq', params: { type: 'hp', freq } });
const lp = (freq) => ({ type: 'peq', params: { type: 'lp', freq } });
const pk = (freq, gain, q = 0.7071) => ({ type: 'peq', params: { type: 'peak', freq, gain, q } });
const gate = (threshold, ratio = 10, release = 100) => ({ type: 'gate', params: { threshold, ratio, attack: 1, release } });
const comp = (threshold, ratio, attack = 1, release = 100) => ({ type: 'compressor', params: { threshold, ratio, attack, release, makeup: 0, autoMakeup: false } });
const lim = (threshold) => ({ type: 'limiter', params: { threshold, release: 100 } });
const gain = (g) => ({ type: 'gain', params: { gain: g } });
const drive = (d) => ({ type: 'drive', params: { drive: d } });
const verb = (room_size, wet, dry = 0.4, damping = 0.5) => ({ type: 'reverb', params: { raw: true, room_size, damping, wet, dry, width: 1 } });
const chor = (rate = 1, depth = 0.25, mix = 0.5, feedback = 0) => ({ type: 'chorus', params: { rate, depth, mix, feedback, delay: 7 } });

const CLASSIC = {
  vocals: [
    ['vocal_crystal_clear', 'Crystal Clear', [hp(80), gate(-40, 4, 250), comp(-20, 2.5, 10, 100), gain(2)]],
    ['vocal_studio_presence', 'Studio Presence', [pk(3000, 3, 1), pk(10000, 4, 0.7), comp(-18, 3, 5), lim(-1)]],
    ['vocal_lush_verb', 'Lush Verb', [hp(150), verb(0.8, 0.4, 0.7, 0.2), chor(1, 0.25, 0.5), gain(-2)]],
    ['vocal_dry_tight', 'Dry Tight', [gate(-25, 8, 50), hp(100), comp(-15, 4, 1, 50)]],
    ['vocal_broadcast', 'Broadcast', [comp(-25, 4, 2, 100), lim(-0.5), gain(4)]],
  ],
  drums: [
    ['drum_punchy_kick', 'Punchy Kick', [pk(60, 6, 2), pk(400, -5, 1), comp(-15, 4, 30, 100), lim(-0.5)]],
    ['drum_crisp_snare', 'Crisp Snare', [drive(5), pk(200, 3), pk(5000, 4), verb(0.3, 0.15)]],
    ['drum_room_killer', 'Room Killer', [gate(-30, 6, 80), hp(30)]],
    ['drum_bus_glue', 'Bus Glue', [comp(-15, 2, 10, 50), drive(2), lim(-0.5)]],
    ['drum_lofi_grit', 'Lofi Grit', [{ type: 'bitcrush', params: { bits: 8 } }, lp(4000), comp(-20, 8)]],
    ['snare_crack', 'Snare Crack', [pk(2000, 6), comp(-15, 4)]],
  ],
  bass: [
    ['bass_sub_focus', 'Sub Focus', [lp(250), comp(-15, 4, 50), lim(-0.5)]],
    ['bass_fuzz_box', 'Fuzz Box', [drive(15), pk(800, -6), comp(-20, 4)]],
    ['bass_even_dynamics', 'Even Dynamics', [comp(-25, 8, 5, 100), gain(4), lim(-0.5)]],
    ['bass_note_definition', 'Note Definition', [pk(800, 5), pk(200, -4, 2), drive(3)]],
    ['bass_rumble_eater', 'Rumble Eater', [hp(35), pk(50, -10, 5)]],
  ],
  other: [
    ['other_stereo_widen', 'Stereo Widen', [chor(0.5, 0.3, 0.5, 0), pk(8000, 3, 0.5)]],
    ['other_warm_tape', 'Warm Tape', [drive(6), lp(14000), comp(-15, 2, 50)]],
    ['other_clean_rhythm', 'Clean Rhythm', [comp(-18, 3), pk(300, -4)]],
    ['other_shimmer', 'Shimmer', [verb(0.9, 0.6, 0.6, 0.1), chor(2, 0.5, 0.5)]],
    ['other_background', 'Background', [verb(0.5, 0.3), pk(3000, -3), gain(-3)]],
  ],
};
const CLASSIC_FOR = { vocals: 'vocals', drums: 'drums', bass: 'bass', other: 'other' };
function classicFamily(kind) {
  if (kind === 'vocals') return 'vocals';
  if (kind === 'bass' || kind === 'sub808') return 'bass';
  if (DRUM_KINDS.includes(kind) && kind !== 'sub808' || kind === 'drums') return 'drums';
  return 'other';
}
function classicPresetsFor(kind) {
  return CLASSIC[CLASSIC_FOR[classicFamily(kind)]].map(([id, name, mods]) => ({
    id: `classic:${id}`, family: 'classic', name, description: 'Classic (DeepSplit) preset',
    chain: mods.map((m) => ({ type: m.type, enabled: true, params: { ...defaultParams(m.type), ...m.params } })),
  }));
}

/* ---------- studio presets (new: drum sub-stems, 808, plus a few clean-up chains) ---------- */
const sh = (type, freq, g, q) => ({ type: 'peq', params: { type, freq, gain: g, q: q || Math.SQRT1_2 } });
const STUDIO = {
  kick: [
    ['kick_punch', 'Punch & Sub', 'Low-end weight, boxiness cut, beater click', [sh('lowshelf', 80, 3), pk(300, -3, 1), pk(4000, 2, 1), comp(-18, 4, 30, 80)]],
    ['kick_tight', 'Tight', 'Gate the ring-out and remove rumble', [gate(-35, 6, 60), hp(30), pk(250, -3, 1)]],
    ['kick_soft_clip', 'Soft Clip Loud', 'Drive + brick-wall for a loud, even kick', [drive(4), lim(-1)]],
  ],
  snare: [
    ['snare_snap', 'Snap', 'Body at 200 Hz, crack at 5 kHz, light compression', [pk(200, 2, 1), pk(5000, 3, 1), comp(-18, 3, 15, 80)]],
    ['snare_room_tamer', 'Room Tamer', 'Shorten the room tail', [{ type: 'dereverb', params: { threshold: -35, amount: 60, release: 150 } }, gate(-40, 3, 120)]],
    ['snare_fat', 'Fat', 'Warmth, body and a short room', [pk(180, 4, 1), { type: 'saturation', params: { drive: 30, mix: 40 } }, { type: 'reverb', params: { room_size: 25, damping: 50, wet: 12, width: 100 } }]],
  ],
  hats: [
    ['hats_smooth', 'Smooth', 'Remove rumble and tame harsh 8 kHz', [hp(300), { type: 'deesser', params: { frequency: 8000, threshold: -25, mode: 'split', ratio: 4 } }, pk(3000, -2, 1)]],
    ['hats_air', 'Air', 'Brighter, thinner hats', [hp(500), sh('highshelf', 10000, 3)]],
    ['hats_tight', 'Tight', 'Cut bleed between hits', [gate(-35, 4, 40), hp(400)]],
  ],
  toms: [
    ['toms_boom', 'Boom', 'Weight and less box', [sh('lowshelf', 100, 3), pk(400, -3, 1), comp(-18, 3, 20, 120)]],
    ['toms_tight', 'Tight Gate', 'Gate the ring and bleed', [gate(-32, 6, 90), hp(50)]],
  ],
  cymbals: [
    ['cymbals_tame', 'Tame Wash', 'Reduce wash and harshness', [{ type: 'dereverb', params: { threshold: -35, amount: 50, release: 200 } }, hp(300), pk(3000, -2, 1)]],
    ['cymbals_sparkle', 'Sparkle', 'Open the top end', [sh('highshelf', 9000, 3), hp(250)]],
  ],
  sub808: [
    ['s808_clean', 'Clean Sub', 'Rumble out, level even', [hp(25), lp(180), comp(-15, 4, 30, 100), lim(-1)]],
    ['s808_harmonics', 'Harmonics', 'Adds upper harmonics so it translates on small speakers', [hp(30), { type: 'saturation', params: { drive: 25, mix: 40 } }, comp(-18, 3, 30, 120)]],
    ['s808_tight', 'Tight', 'Shorten the tail', [gate(-30, 6, 80), hp(28)]],
  ],
  vocals: [
    ['vocals_cleanup', 'Clean-up', 'Rumble out, de-ess, gentle level control', [hp(90), { type: 'deesser', params: { frequency: 7000, threshold: -28, mode: 'split', ratio: 4 } }, comp(-20, 2.5, 10, 100)]],
  ],
};
STUDIO.drums = [];
function studioPresetsFor(kind) {
  const list = STUDIO[kind] || [];
  return list.map(([id, name, description, mods]) => ({
    id: `studio:${id}`, family: 'studio', name, description,
    chain: mods.map((m) => ({ type: m.type, enabled: true, params: { ...defaultParams(m.type), ...m.params } })),
  }));
}

/** All presets for a stem kind: [{id, family, name, description, chain:[{type, enabled, params}]}] */
export function presetsFor(kind) {
  return [...desktopPresetsFor(kind), ...studioPresetsFor(kind), ...classicPresetsFor(kind)];
}

/** An empty chain with the desktop module order for a stem kind (all modules disabled), for manual tweaking. */
export function blankChain(kind) {
  return chainModules(kind).map((t) => ({ type: t, enabled: false, params: defaultParams(t) }));
}

/**
 * Chain to edit for a preset: the preset's modules enabled plus the rest of the stem's desktop modules
 * present but disabled (desktop behaviour), so every knob is reachable.
 */
export function chainFromPreset(kind, preset) {
  if (!preset) return blankChain(kind);
  const used = new Set(preset.chain.map((m) => m.type));
  if (preset.family === 'desktop') {
    const order = chainModules(kind);
    return order.map((t) => preset.chain.find((m) => m.type === t) || { type: t, enabled: false, params: defaultParams(t) })
      .map((m, i) => ({ ...clone(m), id: `${m.type}:${i}` }));
  }
  return preset.chain.map((m, i) => ({ ...clone(m), id: `${m.type}:${i}` }));
}

export function inventory() {
  const kinds = Object.keys(STEM_KINDS);
  return kinds.map((k) => ({ kind: k, presets: presetsFor(k).map((p) => `${p.family}:${p.name}`) }));
}
